const results = await Promise.all(shards.map(processShard));   // Promise<Result[]>
// worker-only phase barrier over shared memory; parent allocates sharedSync once and passes it to every worker:
const sync = new Int32Array(sharedSync);   // slot 0: arrivals, 1: phase
const arriveAndWait = (phase: number, parties: number): boolean => {
  if (Atomics.add(sync, 0, 1) + 1 === parties) {           // last arriver
    Atomics.store(sync, 0, 0);
    Atomics.store(sync, 1, phase + 1);
    Atomics.notify(sync, 1);
    return true;
  }
  while (Atomics.load(sync, 1) === phase) {
    if (Atomics.wait(sync, 1, phase, 5000) === "timed-out") return false;
  }
  return true;
};
if (!arriveAndWait(phase, parties)) throw new Error("barrier timeout");
